pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20 token that only has transfer, not transferFrom
        Token t = new Token();
        address from = address(this);
        address[] memory tos = new address[](1);
        tos[0] = from;
        uint256 v = 100;
        // Mint tokens to 'from' so transfer can succeed
        t.mint(from, v);
        uint256 initialBalance = t.balanceOf(from);
        // Call transfer on C - reference calls transferFrom and will revert because token lacks approval
        // Buggy version calls transfer and will succeed
        // We try/catch to see if it reverts
        bool ok;
        try c.transfer(from, address(t), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // For the reference, ok is false; for the bug, ok is true
        // We assert that the caller's token balance is unchanged (reference behavior)
        // This will pass on reference, fail on bug
        assertTrue(t.balanceOf(from) == initialBalance, "balance unchanged");
    }
}

