        require(balanceOf[msg.sender] >= amount);
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function transferFrom(address, address, uint256) public pure returns (bool) {
        revert("no");
    }
}

