import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that has both transfer and transferFrom
        // We'll use address(this) as the token
        address token = address(0x123);
        address[] memory recipients = new address[](1);
        recipients[0] = address(this); // send to self
        uint256 value = 100;

        // The token at 0x123 has 0 balance initially
        // Reference call uses transferFrom -> needs allowance, will revert
        // Buggy call uses transfer -> succeeds, but transfer to self with balance 0 
        //   actually does nothing (no event, no balance change from token's perspective)
        // To observe divergence, we need a token where the two functions behave differently.
        // Let's use a pre-deployed mock that reverts on transferFrom and succeeds on transfer.
        // Simpler: deploy a minimal token inline

        // Actually the bug is that the reference reverts, the buggy one doesn't.
        bool ok;
        try c.transfer(address(this), token, recipients, value) {
            ok = true;
        } catch {
            ok = false;
        }
        // On the reference, this call will reverts (transferFrom fails), so ok == false
        // On the buggy version, this call succeeds (transfer succeeds), so ok == true
        // Since we are testing the reference, assert false
        assertTrue(ok == false);
    }
}

