// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that only has transfer (not transferFrom)
        // and that checks msg.sender == from
        SimpleToken token = new SimpleToken();
        address alice = address(0x123);
        token.mint(alice, 100);

        address[] memory tos = new address[](1);
        tos[0] = address(0x456);

        vm.prank(alice);
        bool ok;
        try c.transfer(alice, address(token), tos, 10) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (transferFrom) fails because SimpleToken has no transferFrom (reverts)
        // Bug (transfer) succeeds but the transfer call fails because msg.sender != from (reverts internally)
        // However, the bug's inner call reverts, so both revert.
        // We need a different approach: use a token where transfer does NOT check caller
        // and just transfers from 'from' to 'to'

        // Reset: deploy a token that accepts transfer with any caller
        SimpleToken2 token2 = new SimpleToken2();
        token2.mint(alice, 100);
        tos[0] = address(0x456);

        vm.prank(address(0x789)); // some third party
        try c.transfer(alice, address(token2), tos, 10) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (transferFrom not found), bug succeeds (transfer called)
        assertTrue(ok == true); // bug succeeds, but reference would revert
        // But we need to differentiate: check token2 balance of alice
        // In reference, alice keeps 100; in bug, alice loses 10
        assertTrue(token2.balanceOf(alice) == 90);
    }
}

contract SimpleToken2 {
    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amount) public { balanceOf[to] += amount; }
    function transfer(address to, uint256 value) public returns (bool) {
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        return true;
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amount) public { balanceOf[to] += amount; }
}
